let
  //Capture the date range from the parameters
  StartDate = if Date.AddYears(List.Min(#"Tasks"[Start Date]),-5) = null then Date.AddYears(DateTime.Date(DateTime.LocalNow()),-5) else Date.AddYears(List.Min(#"Tasks"[Start Date]),-5),
    #"Extracted StartDate" = Date.From(StartDate),
  EndDate = if Date.AddYears(List.Max(#"Tasks"[Finish Date]), 5) = null then Date.AddYears(DateTime.Date(DateTime.LocalNow()), 5) else Date.AddYears(List.Max(#"Tasks"[Finish Date]), 5),
    #"Extracted EndDate" = Date.From(EndDate),
  //Get the number of dates that will be required for the table
  GetDateCount = Duration.Days(#"Extracted EndDate" - #"Extracted StartDate"),
  //Take the count of dates and turn it into a list of dates
  GetDateList = List.Dates(#"Extracted StartDate", GetDateCount,
    #duration(1,0,0,0)),
  //Convert the list into a table
  DateListToTable = Table.FromList(GetDateList,
    Splitter.SplitByNothing(), {"Date"}, null, ExtraValues.Error),
  //Convert the Date column to a Date type
  ChangeDateToDateType = Table.TransformColumnTypes(DateListToTable,{"Date", type date}),
  //Create various date attributes from the date column
  //Add DateKey
  DateKey = Table.AddColumn(ChangeDateToDateType, "Key", each Number.ToText(Date.Year([Date]))&
         Text.PadStart(Number.ToText(Date.Month([Date])),2,"0")&
         Text.PadStart(Number.ToText(Date.Day([Date])),2,"0")),
  ChangeKeyToNumber = Table.TransformColumnTypes(DateKey,{{"Key", Int64.Type}}),
  MoveKeyToBeginning = Table.ReorderColumns(ChangeKeyToNumber,{"Key", "Date"}),
  // Add Year Column
  Year = Table.AddColumn(MoveKeyToBeginning, "Year", each Date.ToText([Date], "yyyy"), type text),
  // Add Month Number Column
  Month = Table.AddColumn(Year, "Month", each Date.ToText([Date], "MM"), type text),
    #"Added MM-YYYY" = Table.AddColumn(Month, "MM-YYYY", each [Month] & "-" & [Year], type text)
in
    #"Added MM-YYYY"

FILTER(
    DATATABLE(
        "UserPrincipalName", STRING,
        "SecLevel", INTEGER,
        "RoleName", STRING,
        "ScopeType", STRING,
        "ScopeKey", STRING,
        {
            { "example.user@company.com", 5, "Team Member", "Resource", "00000000-0000-0000-0000-000000000000" }
        }
    ),
    FALSE()
)
